head.script:
/* ★Wcraft guide★    
스크립트 수작업 유의사항
*/


//★Wcraft guide★ include부분 주석처리 -> include("../js/libRoundPanel.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/stf.js");
// showObj(ObjID, flag) SetWindowPos(ObjID, nTop, nLeft, nWidth, nHeight)
//★Wcraft guide★ include부분 주석처리 -> include("../js/session.js");
// 세션정보를 얻기위한 함수사용
//★Wcraft guide★ include부분 주석처리 -> include("../js/list_common.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/utils.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/common.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/PopupCalendar.js");
scwin.fr_SecuGrpId;
scwin.fn_GetPar, scwin.fn_SetPar;
scwin.gBzProcsNo;
scwin.fr_MktId;
scwin.gAcptNo;
scwin.gViewerStat; // 처리시 뷰어=P,  조회시 뷰어=R
scwin.gMainFormCd;
scwin.gFormVer;
scwin.gIsurCd;

// 발행기관목록관련
scwin.vScrenID = "ULDSTF05243.xml";
scwin.onpageload = function() {
    scwin.gform_onload();
};
scwin.onpageunload = function() {
};
scwin.fn_GetParIsur = function(arrPar) {
    // 넘길 인수를 지정하는 펑션
    arrPar[0] = $c.stf.getObjectValue(txb_ISUR_CD); // 코드값을 포함할 컨트롤
    arrPar[1] = $c.stf.getObjectValue(txb_COM_NM); // 명칭값을 포함할 컨트롤
    arrPar[2] = scwin.fr_SecuGrpId; // 명칭값을 포함할 컨트롤
    return
    // ********************************************************************
    // [WebSquare 전환 추가] 원본 소스와 비교 필요
    // 
    // ********************************************************************
    arrPar, length;
};
scwin.fn_SetParIsur = function(arrPar) {
    txb_ISUR_CD.setValue(arrPar[0].ISUR_CD);
    txb_COM_NM.setValue(arrPar[0].COM_NM);
    scwin.fr_MktId = arrPar[0].SPOT_ISU_TRD_MKT_TP_CD;
    if (scwin.fr_MktId != '6') {
        $c.win.alert("[소속부변경]업무는 코넥스회사만 해당합니다. 회사를 다시 선택바랍니다");
        return;
    }
    var dbClickYn = arrPar[0].DBCLICKYN;
    if (dbClickYn == "Y") {
        scwin.fn_list_sync();
    }
};
scwin.fn_GetParDetail = function(arrPar) {
    // 넘길 인수를 지정하는 펑션
    arrPar[0] = txb_ISUR_CD.getValue(); // 발행기관코드값
    arrPar[1] = txb_COM_NM.getValue(); // 발행기관명
    arrPar[2] = scwin.fr_SecuGrpId; // 증권그룹구분	
    arrPar[3] = scwin.fr_MktId; // 시장구분
    arrPar[4] = dts_List.getCellData(dts_List.getRowPosition(), "BZ_PROCS_NO"); // 업무처리번호

    return arrPar.length;
};
scwin.fn_GetParNew = function(arrPar) {
    // 신규생성시 지정하는 평션
    arrPar[0] = txb_ISUR_CD.getValue(); // 발행기관코드값
    arrPar[1] = txb_COM_NM.getValue(); // 발행기관명
    arrPar[2] = scwin.fr_SecuGrpId; // 증권그룹구분	
    arrPar[3] = scwin.fr_MktId; // 시장구분
    arrPar[4] = ""; // 신규작성시 업무처리번호는 없다.

};
scwin.fn_list_sync = function() {
    var url = "/listingCommon.do?SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01 + "&method=listGeneral&outputMessageId=SECT_TYP_CHG_INOUT" + "&service=krx.lds.stf.listingcommon.services.ListingCommonApp" + "&queryId=lds.stf.lstproc.konex.scttypchg.select.list.search" + "&{P}param01=" + txb_ISUR_CD.getValue() + "&{P}param02=" + txb_ISUR_CD.getValue() + "&{P}param03=" + txb_ISUR_CD.getValue() + "&{P}param04=" + txb_ISUR_CD.getValue() + "&{P}param05=" + txb_ISUR_CD.getValue() + "&{P}param06=" + txb_ISUR_CD.getValue() + "&{P}param07=" + txb_ISUR_CD.getValue();
    dts_List.DataID = encodeURI(url);
    dts_List.Reset();
    $c.cm.ShowWin(grd_List);
};
scwin.fn_OpenDetail = async function() {
    await $c.frame.CreateDialogFrame("ULDSTF05244.gfm", "/lstproc/ULDSTF05244.gfm", "소속부변경 관리", 200, 200, 645 + 70, 330 + 30, "window");
};


// 클릭된 값 변수에 셋팅
scwin.fn_OpenRecvDetail = function(row, colid) {
    scwin.fn_setContnId(row);
    if (scwin.gAcptNo != "") {
        $c.stf.fn_OpenDisclViewer(scwin.gAcptNo, scwin.gViewerStat);
    }
};
scwin.fn_setContnId = function(obj) {
    if (eval(obj) > 0) {
        //그리드에서 선택시
        scwin.gAcptNo = dts_List.getCellData(eval(obj), "ACPT_NO");
        scwin.gMainFormCd = dts_List.getCellData(eval(obj), "FORM_CD");
        scwin.gFormVer = dts_List.getCellData(eval(obj), "FORM_VER");
        scwin.gIsurCd = dts_List.getCellData(eval(obj), "DISCLS_ISUR_CD");
        scwin.gViewerStat = "R"; // 처리시 뷰어=P,  조회시 뷰어=R
        //alert("gBzProcsNo():"+gBzProcsNo);
        //alert("gAcptNo():"+gAcptNo);
        //alert("gIsurCd():"+gIsurCd);
        //alert("gListProcsStatCd():"+gListProcsStatCd);

    }
};
scwin.img_COM_NM_onclick = function() {
    scwin.fn_GetPar = fn_GetParIsur;
    scwin.fn_SetPar = fn_SetParIsur;
    $c.lc.fn_PopFindCorpChrg(scwin.fr_SecuGrpId);
};
scwin.btn_Search_onclick = function() {
    if ($c.stf.getObjectValue(txb_ISUR_CD) == "") {
        $c.win.alert("[회사]를 선택하세요.");
        txb_ISUR_CD.focus();
        return;
    }
    scwin.fn_list_sync();
};
scwin.btn_New_onclick = function() {
    if ($c.stf.getObjectValue(txb_ISUR_CD) == "") {
        $c.win.alert("[회사]를 선택하세요.");
        txb_ISUR_CD.focus();
        return;
    }
    scwin.fn_GetPar = fn_GetParNew;
    scwin.fn_SetPar = undefined;
    scwin.fn_OpenDetail();
};
scwin.img_Excel_onclick = function() {
    if (dts_List.getTotalRow() > 0) {
        //엑셀 로그 
        $c.stf.doLogSave(scwin.vScrenID, SCREN_PROCS_TP_CD_07);
        $c.data.downloadGridViewExcel(grd_List, $c.lc.fn_getSecuGrpNm(scwin.fr_SecuGrpId) + "업종변경내역", "", "8");
    } else {
        $c.win.alert(NO_EXCEL_DATA);
    }
};
scwin.grd_List_OnDblClick = function(row, colid) {
    if (colid == "SECT_CHG_GRND_REGUL_NM") {
        if (dts_List.getCellData(row, colid) != '') scwin.fn_OpenRecvDetail(row, colid);
    } else {
        scwin.fn_GetPar = fn_GetParDetail; // 수정시 인수를 넘기는 function을 fn_GetPar란 변수에 할당, (팝업화면에서 참조하는 변수명이 fn_GetPar임)
        scwin.fn_SetPar = undefined;
        scwin.fn_OpenDetail();
    }
};
scwin.dts_List_OnLoadCompleted = function(rowcount) {
    $c.stf.FillGridHeaderTotalCnt(rowcount, panel_page);
    $c.cm.CloseWin(rowcount, grd_List);
};
scwin.dts_List_OnLoadError = function() {
    $c.stf.alert_error(dts_List);
};
scwin.btn_Close_onclick = async function() {
    await $c.frame.CloseFrame();
};
scwin.gform_onload = function() {
    $c.cm.PanelToGroupBox(panel_Top);
    if (js_market == "9") {
        $c.stf.showObj(btn_New, true);
    } else {
        $c.stf.showObj(btn_New, false);
    }
};
